function rateTicket(store, customer, id, score, { now = new Date() } = {}) {
  const t = getMyTicket(store, customer, id);
  if (!t) return null;
  if (!Number.isInteger(score) || score < 1 || score > 5) throw new Error('rating score must be a whole number from 1 to 5');
  if (t.status !== STATUS.RESOLVED) throw new Error(`cannot rate a ${t.status} ticket`);
  if (store.getRating(id)) throw new Error('this ticket already has a rating');
  store.setRating(id, { score, owner_id: t.assignee_id, rated_at: now.toISOString() });
  if (score <= 2 && t.assignee_id) notifyAgent(store, t.assignee_id, { type: 'ticket_rated', ticketId: id, score });
  return store.getRating(id);
}
```

