'use strict';
// Nightly. Writes exports/rating-summary.json: for each agent with at least one rating in the past seven
// days, how many ratings they received and the average score.
const fs = require('node:fs');
const path = require('node:path');
const { EXPORT_DIR } = require('./export-tickets');

const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function ratingSummary(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
  const byOwner = new Map();
  for (const r of store.listRatings()) {
    if (!r.owner_id) continue;
    if (now.getTime() - new Date(r.rated_at).getTime() >= WINDOW_DAYS * DAY) continue;
    const bucket = byOwner.get(r.owner_id) || [];
    bucket.push(r.score);
    byOwner.set(r.owner_id, bucket);
  }
  const rows = [...byOwner.entries()].map(([owner_id, scores]) => ({
    owner_id,
    ratings: scores.length,
    average: Math.round((scores.reduce((a, b) => a + b, 0) / scores.length) * 100) / 100,
  }));
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, 'rating-summary.json');
  fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
  return { file, rows };
}

module.exports = { ratingSummary, WINDOW_DAYS };
```

